import React, { useEffect, useState } from 'react';
import { getCar } from '../services/carService';
import { getImageUrl } from '../services/api';
import { motion } from 'framer-motion';
import styles from './ComparePage.module.css';

const ComparePage = () => {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const compareIds = JSON.parse(localStorage.getItem('compareList') || '[]');

  useEffect(() => {
    if (compareIds.length === 0) {
      setLoading(false);
      return;
    }
    const fetchCars = async () => {
      try {
        const promises = compareIds.map(id => getCar(id));
        const results = await Promise.all(promises);
        setCars(results.map(res => res.data));
      } catch (err) {
        console.error('Ошибка загрузки сравнения', err);
      } finally {
        setLoading(false);
      }
    };
    fetchCars();
  }, [compareIds]);

  const clearCompare = () => {
    localStorage.removeItem('compareList');
    window.location.reload();
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;
  if (compareIds.length === 0) return <div className={styles.empty}>Нет автомобилей для сравнения. Добавьте их из каталога.</div>;

  const attributes = [
    { key: 'image_url', label: 'Фото' },
    { key: 'brand', label: 'Марка' },
    { key: 'model', label: 'Модель' },
    { key: 'year', label: 'Год' },
    { key: 'price', label: 'Цена' },
    { key: 'body_type', label: 'Кузов' },
    { key: 'restyling', label: 'Рестайлинг' },
    { key: 'description', label: 'Описание' },
  ];

  return (
    <motion.div className={styles.page} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <div className={styles.header}>
        <h1 className={styles.title}>Сравнение автомобилей</h1>
        <button className={styles.clearBtn} onClick={clearCompare}>Очистить список</button>
      </div>
      <div className={styles.tableWrapper}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Характеристика</th>
              {cars.map(car => (
                <th key={car.id} className={styles.carHeader}>
                  {car.brand} {car.model}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {attributes.map(attr => (
              <tr key={attr.key}>
                <td className={styles.attrName}>{attr.label}</td>
                {cars.map(car => (
                  <td key={car.id} className={styles.attrValue}>
                    {attr.key === 'image_url' ? (
                      <img src={getImageUrl(car.image_url)} alt={car.model} className={styles.carImage} />
                    ) : attr.key === 'price' ? (
                      `${car.price.toLocaleString()} ₽`
                    ) : attr.key === 'restyling' ? (
                      car.restyling ? 'Да' : 'Нет'
                    ) : (
                      car[attr.key]
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </motion.div>
  );
};

export default ComparePage;
